-- ======================================================================
-- API 权限登记补齐（权限覆盖矩阵产出）
-- 目标库：db_permission
-- 依赖：002_rbac_permission.sql（菜单与既有 system:* 权限）
-- 版本：019（seed 目录，按 018_notify.sql 之后顺延）
--
-- 目的：
--   为 22 个无方法级 @PreAuthorize 的业务服务补齐 URL 权限登记（24 个有 Controller 的服务中，
--   scm-auth 与 scm-system 已有方法级注解；其余 22 个本轮按矩阵补齐），
--   覆盖管理端与混合端（管理端/用户自助共用）路由。
--
-- 范围与计数：
--   管理端 + 混合端合计 553 条：literal 203 条，templated 350 条。
--   - 第 1 段（literal）：当前 ApiAccessControlFilter + SysPermissionMapper.findPermissionsByUrl
--     使用 api_path 精确匹配，可直接生效。
--   - 第 2 段（templated）：api_path 含 {var} 占位符，需先把 findPermissionsByUrl 升级为
--     Ant/占位符匹配后才会生效；本段只登记定义，不改变当前放行行为。
--
-- 不在本脚本内：
--   - 公开端点（登录/刷新/支付渠道回调）
--   - 内部服务间端点（审计写入已由 AuditWriteRequestGuard 验签；权限查询、库存预占、
--     搜索索引、通知审计写入需在 fail-closed 前补签名/白名单）
--   - 用户自助端点（购物车、收货地址、积分、通知、优惠券、个性化推荐等）
--     这些必须做“当前登录人 == 目标 userId”校验，不能靠权限码。
--
-- 幂等：
--   permission_code 全局唯一，使用固定 UUID v5 + ON CONFLICT 更新；
--   角色绑定使用 ON CONFLICT (role_id, permission_id) DO NOTHING。
--   可重复执行。
--
-- 执行：
--   psql -h localhost -U admin -d db_permission -v ON_ERROR_STOP=1 \
--        -f scripts/db/seed/019_api_permission_coverage.sql
-- ======================================================================

BEGIN;

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- ----------------------------------------------------------------------
-- 1. 可直接生效的 API 权限（api_path 为字面量，精确匹配）
-- ----------------------------------------------------------------------
INSERT INTO sys_permission (
    id, parent_id, permission_code, permission_name, permission_type,
    api_path, http_method, sort_order, visible, status,
    tenant_id, permission_scope, permission_level, risk_level,
    need_approval, need_two_factor, create_time, update_time, deleted
)
SELECT uuid_generate_v5(uuid_ns_url(), 'scm:perm:' || v.code),
       (SELECT p.id FROM sys_permission p WHERE p.permission_code = v.parent LIMIT 1),
       v.code, v.name, 3, v.api, v.method, v.sort_order,
