ON CONFLICT (permission_code) DO UPDATE SET
    parent_id = EXCLUDED.parent_id,
    permission_name = EXCLUDED.permission_name,
    permission_type = 3,
    api_path = EXCLUDED.api_path,
    http_method = EXCLUDED.http_method,
    sort_order = EXCLUDED.sort_order,
    risk_level = EXCLUDED.risk_level,
    visible = TRUE,
    status = 1,
    tenant_id = EXCLUDED.tenant_id,
    permission_scope = EXCLUDED.permission_scope,
    update_time = NOW(),
    deleted = FALSE;

-- ----------------------------------------------------------------------
-- 3. 角色绑定
--    SUPER_ADMIN：全部新增权限
--    TENANT_ADMIN：除 tenant:* 平台管理外的全部新增权限
--    （租户管理员不应能创建/停用/删除其他租户）
-- ----------------------------------------------------------------------
INSERT INTO sys_role_permission (id, role_id, permission_id, tenant_id, create_time)
SELECT uuid_generate_v5(uuid_ns_url(), 'scm:rp:' || r.role_code || ':' || p.permission_code),
       r.id, p.id, r.tenant_id, NOW()
FROM sys_role r
JOIN sys_permission p
  ON p.tenant_id = '019a0aee-0000-7000-8000-000000000002'
 AND p.status = 1
 AND NOT p.deleted
WHERE r.tenant_id = '019a0aee-0000-7000-8000-000000000002'
  AND r.role_code = 'ROLE_SUPER_ADMIN'
  AND (p.permission_code ~ '^(analytics|approval|audit|document|file|finance|fulfillment|inventory|logistics|mall|member|notify|order|order-center|payment|product|promotion|purchase|search|supplier|tenant|warehouse):'
       OR p.permission_code ~ '^system:decision-(rule|weight):'
       OR p.permission_code ~ '^system:status:')
ON CONFLICT (role_id, permission_id) DO NOTHING;

INSERT INTO sys_role_permission (id, role_id, permission_id, tenant_id, create_time)
SELECT uuid_generate_v5(uuid_ns_url(), 'scm:rp:' || r.role_code || ':' || p.permission_code),
       r.id, p.id, r.tenant_id, NOW()
FROM sys_role r
JOIN sys_permission p
  ON p.tenant_id = '019a0aee-0000-7000-8000-000000000002'
 AND p.status = 1
 AND NOT p.deleted
WHERE r.tenant_id = '019a0aee-0000-7000-8000-000000000002'
  AND r.role_code = 'ROLE_TENANT_ADMIN'
  AND (p.permission_code ~ '^(analytics|approval|audit|document|file|finance|fulfillment|inventory|logistics|mall|member|notify|order|order-center|payment|product|promotion|purchase|search|supplier|warehouse):'
       OR p.permission_code ~ '^system:decision-(rule|weight):'
       OR p.permission_code ~ '^system:status:')
ON CONFLICT (role_id, permission_id) DO NOTHING;

COMMIT;

